import {useEffect, useMemo, useState} from 'react';
import transform from '@diplodoc/transform';
import plugins from '@diplodoc/transform/lib/plugins';
import {YfmStaticView, type MarkupString, type RenderPreviewParams} from '@gravity-ui/markdown-editor';
import {useThemeValue} from '@gravity-ui/uikit';

import '@diplodoc/transform/dist/css/yfm.css';

type MarkdownPreviewProps = {
  getValue: () => MarkupString;
  md: RenderPreviewParams['md'];
};

const RENDER_DELAY_MS = 150;

/** Renders the current markup to HTML. Re-rendered by the editor on every change. */
export function MarkdownPreview({getValue, md}: MarkdownPreviewProps) {
  const [html, setHtml] = useState('');
  const theme = useThemeValue();
  const markup = getValue();

  const options = useMemo(
    () => ({
      allowHTML: md.html,
      breaks: md.breaks,
      linkify: md.linkify,
      linkifyTlds: md.linkifyTlds,
      plugins,
    }),
    [md.html, md.breaks, md.linkify, md.linkifyTlds],
  );

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setHtml(transform(markup, options).result.html);
    }, RENDER_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [markup, options, theme]);

  return <YfmStaticView html={html} mods={{'no-list-reset': true}} />;
}
EOF
cat > src/MarkdownField.tsx <<'EOF'
import {useCallback, useEffect} from 'react';
import {
  MarkdownEditorView,
  useMarkdownEditor,
  type MarkupString,
  type RenderPreview,
} from '@gravity-ui/markdown-editor';
import {Text} from '@gravity-ui/uikit';

import {MarkdownPreview} from './MarkdownPreview';

type MarkdownFieldProps = {
  label: string;
  value: MarkupString;
  onChange: (value: MarkupString) => void;
  placeholder?: string;
};

/**
 * Form field for markdown text. The user types raw markup on the left and
 * sees the rendered result on the right, updated as they type.
 */
export function MarkdownField({label, value, onChange, placeholder}: MarkdownFieldProps) {
  const renderPreview = useCallback<RenderPreview>(
    ({getValue, md}) => <MarkdownPreview getValue={getValue} md={md} />,
    [],
  );

  const editor = useMarkdownEditor({
    md: {html: false, linkify: true, breaks: true},
    initial: {markup: value, mode: 'markup', splitModeEnabled: true, toolbarVisible: true},
    markupConfig: {renderPreview, splitMode: 'horizontal', placeholder},
  });

  useEffect(() => {
    const handleChange = () => onChange(editor.getValue());
    editor.on('change', handleChange);
    return () => {
      editor.off('change', handleChange);
    };
  }, [editor, onChange]);

  return (
    <label style={{display: 'flex', flexDirection: 'column', gap: 'var(--g-spacing-2)'}}>
      <Text variant="subheader-1">{label}</Text>
      <div
        style={{
          minHeight: 320,
          border: '1px solid var(--g-color-line-generic)',
          borderRadius: 'var(--g-border-radius-m)',
          overflow: 'hidden',
        }}
      >
        <MarkdownEditorView editor={editor} stickyToolbar={false} settingsVisible={['mode', 'split']} />
      </div>
    </label>
  );
}
EOF
cat > src/App.tsx <<'EOF'
import {useCallback, useState, type FormEvent} from 'react';
import {Button, Flex, Text, TextInput, Toaster, ToasterComponent, ToasterProvider, useToaster} from '@gravity-ui/uikit';
import type {MarkupString} from '@gravity-ui/markdown-editor';

import {MarkdownField} from './MarkdownField';

const toaster = new Toaster();

const INITIAL_DESCRIPTION: MarkupString = `## Описание

Напишите текст с **markdown**-разметкой — справа сразу появится результат.

- список
- [ссылка](https://gravity-ui.com)
- \`код\`
`;

function PostForm() {
  const {add} = useToaster();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState<MarkupString>(INITIAL_DESCRIPTION);

  const handleDescriptionChange = useCallback((value: MarkupString) => setDescription(value), []);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    add({
      name: 'post-form-submitted',
      title: 'Форма отправлена',
      content: `Заголовок: ${title || '—'}, описание: ${description.length} символов`,
      theme: 'success',
    });
  };

  return (
    <form onSubmit={handleSubmit} style={{maxWidth: 960}}>
      <Flex direction="column" gap={4}>
        <Text variant="header-1">Новая запись</Text>
        <TextInput
          size="l"
          label="Заголовок"
          placeholder="Введите заголовок"
          value={title}
          onUpdate={setTitle}
        />
        <MarkdownField
          label="Описание"
          value={description}
          onChange={handleDescriptionChange}
          placeholder="Текст с markdown-разметкой"
        />
        <Flex gap={2}>
          <Button type="submit" view="action" size="l">
            Сохранить
          </Button>
          <Button type="reset" view="flat" size="l" onClick={() => setTitle('')}>
            Очистить заголовок
          </Button>
        </Flex>
      </Flex>
    </form>
  );
}

export function App() {
  return (
    <ToasterProvider toaster={toaster}>
      <div style={{padding: 'var(--g-spacing-6)'}}>
        <PostForm />
      </div>
      <ToasterComponent />
    </ToasterProvider>
  );
}
EOF
